(12, 1, 3, 'course_plan', 'course_plan', '{\"subject\":\"Web Technologies\",\"credits\":\"4\",\"university\":\"Autonomous\",\"template\":\"standard\"}', '{\"title\":\"Web Technologies \\u00b7 Course Plan\",\"subject\":\"Web Technologies\",\"learning_outcomes\":[\"Understand foundational concepts\",\"Apply skills to academic and industry contexts\",\"Analyze problems using higher-order thinking\"],\"units\":[{\"unit_number\":1,\"title\":\"Unit 1 \\u2013 WEB FUNDAMENTALS AND HTML \\u2014 12 Hours\",\"hours\":12,\"topics\":[\"WEB FUNDAMENTALS AND HTML \\u2014 12 Hours\",\"Introduction to the Internet and World Wide Web\",\"client-server architecture\",\"web browsers and web servers\",\"HTTP and HTTPS protocols\",\"URLs and domain names. HTML fundamentals\",\"document structure\",\"elements and attributes\",\"headings\",\"paragraphs\",\"links\",\"images\",\"lists\",\"tables\",\"forms and form controls. Semantic HTML and HTML5 structural elements\"],\"outcomes\":[\"Explain key concepts of WEB FUNDAMENTALS AND HTML \\u2014 12 Hours\",\"Apply techniques related to WEB FUNDAMENTALS AND HTML \\u2014 12 Hours\"],\"bloom_k_level\":\"K1\",\"teaching_methods\":[\"Lecture\",\"Discussion\",\"Demo\"],\"assessment\":[\"Quiz\",\"Assignment\"]},{\"unit_number\":2,\"title\":\"Unit 2 \\u2013 CSS AND RESPONSIVE WEB DESIGN \\u2014 12 Hours\",\"hours\":12,\"topics\":[\"CSS AND RESPONSIVE WEB DESIGN \\u2014 12 Hours\",\"Introduction to CSS\",\"syntax and selectors\",\"colors\",\"backgrounds\",\"fonts and text styling\",\"box model\",\"margins\",\"padding and borders. Display and positioning\",\"floating and clearing\",\"Flexbox and CSS Grid. Responsive web design\",\"media queries\",\"mobile-first design and basic web accessibility\"],\"outcomes\":[\"Explain key concepts of CSS AND RESPONSIVE WEB DESIGN \\u2014 12 Hours\",\"Apply techniques related to CSS AND RESPONSIVE WEB DESIGN \\u2014 12 Hours\"],\"bloom_k_level\":\"K2\",\"teaching_methods\":[\"Lecture\",\"Discussion\",\"Demo\"],\"assessment\":[\"Quiz\",\"Assignment\"]},{\"unit_number\":3,\"title\":\"Unit 3 \\u2013 JAVASCRIPT AND DOM \\u2014 12 Hours\",\"hours\":12,\"topics\":[\"JAVASCRIPT AND DOM \\u2014 12 Hours\",\"Introduction to JavaScript\",\"variables\",\"data types\",\"operators and expressions. Conditional statements\",\"loops\",\"functions\",\"arrays and objects. Events and event handling\",\"Document Object Model (DOM)\",\"selecting and modifying HTML elements\",\"form validation\",\"browser storage and basic asynchronous JavaScript\"],\"outcomes\":[\"Explain key concepts of JAVASCRIPT AND DOM \\u2014 12 Hours\",\"Apply techniques related to JAVASCRIPT AND DOM \\u2014 12 Hours\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Lecture\",\"Discussion\",\"Demo\"],\"assessment\":[\"Quiz\",\"Assignment\"]},{\"unit_number\":4,\"title\":\"Unit 4 \\u2013 SERVER-SIDE WEB DEVELOPMENT \\u2014 12 Hours\",\"hours\":12,\"topics\":[\"SERVER-SIDE WEB DEVELOPMENT \\u2014 12 Hours\",\"Introduction to server-side programming\",\"client-side versus server-side processing\",\"server architecture and request-response lifecycle. PHP fundamentals\",\"variables\",\"data types\",\"operators\",\"control structures\",\"functions\",\"arrays and forms. Form processing\",\"sessions\",\"cookies\",\"file handling and database connectivity using PHP and MySQL\"],\"outcomes\":[\"Explain key concepts of SERVER-SIDE WEB DEVELOPMENT \\u2014 12 Hours\",\"Apply techniques related to SERVER-SIDE WEB DEVELOPMENT \\u2014 12 Hours\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Lecture\",\"Discussion\",\"Demo\"],\"assessment\":[\"Quiz\",\"Assignment\"]},{\"unit_number\":5,\"title\":\"Unit 5 \\u2013 WEB APPLICATIONS, APIs AND SECURITY \\u2014 12 Hours\",\"hours\":12,\"topics\":[\"WEB APPLICATIONS, APIs AND SECURITY \\u2014 12 Hours\",\"Introduction to web application architecture\",\"REST principles and HTTP methods. JSON and API communication\",\"AJAX and asynchronous requests. Authentication and authorization\",\"session management and basic web security. Common web vulnerabilities including SQL injection\",\"Cross-Site Scripting (XSS) and Cross-Site Request Forgery (CSRF). Introduction to deployment\",\"hosting and web application maintenance\"],\"outcomes\":[\"Explain key concepts of WEB APPLICATIONS, APIs AND SECURITY \\u2014 12 Hours\",\"Apply techniques related to WEB APPLICATIONS, APIs AND SECURITY \\u2014 12 Hours\"],\"bloom_k_level\":\"K5\",\"teaching_methods\":[\"Lecture\",\"Discussion\",\"Demo\"],\"assessment\":[\"Quiz\",\"Assignment\"]}],\"weekly_plan\":[{\"week\":1,\"focus\":\"Orientation & Unit 1\"},{\"week\":2,\"focus\":\"Unit 1 continued\"},{\"week\":3,\"focus\":\"Unit 2\"}],\"resources\":[\"Textbook: Standard university recommended text\",\"NPTEL \\/ SWAYAM modules\",\"Lab manuals \\/ case packs\"],\"expert_advice\":[\"Balance K1-K3 with K4-K6 activities for NBA OBE evidence.\",\"Map each CLO to assessments explicitly.\"],\"bloom_distribution\":{\"K1\":15,\"K2\":20,\"K3\":25,\"K4\":20,\"K5\":12,\"K6\":8},\"ai_score\":78,\"demo\":true}', 'gemini-2.5-flash', NULL, NULL, 0, 'success', NULL, NULL, NULL, '2026-08-26 06:45:18');
