INSERT INTO `plan_reviews` (`id`, `plan_id`, `reviewer_id`, `action`, `comments`, `checklist`, `created_at`) VALUES
(1, 1, 2, 'comment', 'The course plan is well structured and covers the major Engineering Mathematics topics. However, CLO-to-assessment mapping, Bloom\'s taxonomy mapping, and the weekly coverage need further refinement for proper OBE/NBA documentation. Please address the highlighted suggestions and resubmit the revised version for approval.. 1 item must be fixed. 5 suggestions', '{\"overall\":\"The course plan is well structured and covers the major Engineering Mathematics topics. However, CLO-to-assessment mapping, Bloom\'s taxonomy mapping, and the weekly coverage need further refinement for proper OBE\\/NBA documentation. Please address the highlighted suggestions and resubmit the revised version for approval.\",\"points\":[{\"key\":\"overview\",\"label\":\"Course overview\",\"comment\":\"The course overview is clear and covers the major mathematical concepts. Please ensure the final syllabus aligns with the approved CSE curriculum.\",\"flag\":\"ok\"},{\"key\":\"outcomes\",\"label\":\"Learning outcomes\",\"comment\":\"Learning outcomes are appropriate. Please map each learning outcome explicitly to the corresponding CLOs and assessments for better OBE documentation.\",\"flag\":\"suggest\"},{\"key\":\"unit:1\",\"label\":\"Unit 1 · Unit 1 · Core Concepts\",\"comment\":\"Unit content is appropriate. Please include specific topic-level outcomes and ensure the topics are aligned with CLO1.\",\"flag\":\"ok\"},{\"key\":\"unit:2\",\"label\":\"Unit 2 · Unit 2 · Core Concepts\",\"comment\":\"Unit content is appropriate. Ensure the differential equation applications are connected to relevant engineering problems.\",\"flag\":\"ok\"},{\"key\":\"unit:3\",\"label\":\"Unit 3 · Unit 3 · Core Concepts\",\"comment\":\"Please provide more specific topics and engineering applications for this unit and map them clearly to the relevant CLO.\",\"flag\":\"suggest\"},{\"key\":\"unit:4\",\"label\":\"Unit 4 · Unit 4 · Core Concepts\",\"comment\":\"Add application-oriented examples and ensure the unit outcomes demonstrate appropriate higher-order learning.\",\"flag\":\"suggest\"},{\"key\":\"unit:5\",\"label\":\"Unit 5 · Unit 5 · Core Concepts\",\"comment\":\"Include practical engineering applications and ensure CLO5 is explicitly mapped to assessment components.\",\"flag\":\"suggest\"},{\"key\":\"bloom\",\"label\":\"Bloom\'s mapping\",\"comment\":\"Please provide a clear CLO-to-Bloom\'s-level mapping. The current view does not provide sufficient evidence for K1–K6 balance and OBE compliance.\",\"flag\":\"must_fix\"},{\"key\":\"weekly\",\"label\":\"Weekly plan\",\"comment\":\"The weekly plan should cover all five units and include appropriate assessment\\/revision periods rather than only the initial units.\",\"flag\":\"suggest\"},{\"key\":\"resources\",\"label\":\"Resources\",\"comment\":\"Recommended resources are appropriate. Please ensure the final resource list contains specific textbooks and valid learning-resource references.\",\"flag\":\"ok\"},{\"key\":\"advice\",\"label\":\"Expert advice\",\"comment\":\"The recommendations are useful. Please incorporate explicit CLO-to-assessment mapping before final approval.\",\"flag\":\"ok\"}]}', '2026-08-26 05:40:30'),
