(1, 4, 3, 23, 'Unit - 1', 12, '[{\"number\":1,\"title\":\"Unit - 1\",\"bullets\":[\"Subject: Web Technologies\",\"Focus: Unit 1\",\"Academic lecture presentation\",\"Includes learning outcomes, concepts, examples, and summary\"],\"speaker_notes\":\"Welcome students. Introduce Web Technologies Unit 1 and outline the session goals.\",\"unit_tag\":\"Unit 1\"},{\"number\":2,\"title\":\"Learning Outcomes\",\"bullets\":[\"Recall key terminology used in Web Technologies Unit 1\",\"Explain the core concepts covered in this unit\",\"Apply basic techniques from Unit 1 to simple problems\",\"Identify common mistakes and how to avoid them\"],\"speaker_notes\":\"State outcomes clearly so students know what success looks like by the end of the lecture.\",\"unit_tag\":\"Unit 1\"},{\"number\":3,\"title\":\"Unit 1 Overview\",\"bullets\":[\"1. Unit 1 – WEB FUNDAMENTALS AND HTML — 12 Hours\",\"2. WEB FUNDAMENTALS AND HTML — 12 Hours\",\"3. Introduction to the Internet and World Wide Web\",\"4. client-server architecture\",\"5. web browsers and web servers\",\"6. HTTP and HTTPS protocols\"],\"speaker_notes\":\"Walk through the Unit 1 agenda. Emphasize connections between topics.\",\"unit_tag\":\"Unit 1\"},{\"number\":4,\"title\":\"Unit 1 – WEB FUNDAMENTALS AND HTML — 12 Hours\",\"bullets\":[\"Definition: Unit 1 – WEB FUNDAMENTALS AND HTML — 12 Hours in Web Technologies\",\"Why this concept matters in Unit 1\",\"Key terms and related ideas students must remember\",\"Connection to the next idea: WEB FUNDAMENTALS AND HTML — 12 Hours\"],\"speaker_notes\":\"Explain Unit 1 – WEB FUNDAMENTALS AND HTML — 12 Hours slowly with a board example. Check prior knowledge before moving deeper into Unit 1 of Web Technologies.\",\"unit_tag\":\"Unit 1\"},{\"number\":5,\"title\":\"WEB FUNDAMENTALS AND HTML — 12 Hours\",\"bullets\":[\"Core idea of WEB FUNDAMENTALS AND HTML — 12 Hours\",\"Step-by-step explanation suitable for classroom teaching\",\"Short example or illustration from Unit 1\",\"Tip: avoid confusing this with similar concepts\"],\"speaker_notes\":\"Ask one student to restate WEB FUNDAMENTALS AND HTML — 12 Hours in their own words. Clarify misconceptions immediately.\",\"unit_tag\":\"Unit 1\"},{\"number\":6,\"title\":\"Introduction to the Internet and World Wide Web\",\"bullets\":[\"Where Introduction to the Internet and World Wide Web is used in Web Technologies\",\"Important rules \\/ properties to highlight\",\"Classroom demo or board work suggestion\",\"Quick practice prompt for students\"],\"speaker_notes\":\"Link Introduction to the Internet and World Wide Web to a short class activity or quiz item. Keep examples aligned to Unit 1.\",\"unit_tag\":\"Unit 1\"},{\"number\":7,\"title\":\"client-server architecture\",\"bullets\":[\"Exam focus: common questions on client-server architecture\",\"What markers usually expect in answers\",\"One worked-style talking point for lecture delivery\",\"Bridge to revision and upcoming topics\"],\"speaker_notes\":\"Explain client-server architecture slowly with a board example. Check prior knowledge before moving deeper into Unit 1 of Web Technologies.\",\"unit_tag\":\"Unit 1\"},{\"number\":8,\"title\":\"web browsers and web servers\",\"bullets\":[\"Definition: web browsers and web servers in Web Technologies\",\"Why this concept matters in Unit 1\",\"Key terms and related ideas students must remember\",\"Connection to the next idea: HTTP and HTTPS protocols\"],\"speaker_notes\":\"Ask one student to restate web browsers and web servers in their own words. Clarify misconceptions immediately.\",\"unit_tag\":\"Unit 1\"},{\"number\":9,\"title\":\"HTTP and HTTPS protocols\",\"bullets\":[\"Core idea of HTTP and HTTPS protocols\",\"Step-by-step explanation suitable for classroom teaching\",\"Short example or illustration from Unit 1\",\"Tip: avoid confusing this with similar concepts\"],\"speaker_notes\":\"Link HTTP and HTTPS protocols to a short class activity or quiz item. Keep examples aligned to Unit 1.\",\"unit_tag\":\"Unit 1\"},{\"number\":10,\"title\":\"URLs and domain names. HTML fundamentals\",\"bullets\":[\"Where URLs and domain names. HTML fundamentals is used in Web Technologies\",\"Important rules \\/ properties to highlight\",\"Classroom demo or board work suggestion\",\"Quick practice prompt for students\"],\"speaker_notes\":\"Explain URLs and domain names. HTML fundamentals slowly with a board example. Check prior knowledge before moving deeper into Unit 1 of Web Technologies.\",\"unit_tag\":\"Unit 1\"},{\"number\":11,\"title\":\"Unit 1 Summary\",\"bullets\":[\"Reviewed the main ideas of Web Technologies Unit 1\",\"Connected definitions, methods, and simple applications\",\"Highlighted common errors and exam-focused points\",\"Prepare practice problems before the next class\"],\"speaker_notes\":\"Recap in 2–3 minutes. Ask students which concept needs more practice.\",\"unit_tag\":\"Unit 1\"},{\"number\":12,\"title\":\"Check Your Understanding\",\"bullets\":[\"What is the most important idea from Unit 1 – WEB FUNDAMENTALS AND HTML — 12 Hours?\",\"How is WEB FUNDAMENTALS AND HTML — 12 Hours used in a simple Web Technologies task?\",\"Name one common mistake students make in Unit 1\",\"Write one short example or definition before leaving class\"],\"speaker_notes\":\"Use as exit ticket or oral Q&A. Collect 2–3 responses to assess understanding.\",\"unit_tag\":\"Unit 1\"}]', 'ready', '{\"subject\":\"Web Technologies\",\"unit\":1,\"plan_id\":4,\"branding\":{\"institution_id\":1,\"name\":\"K.L.N College of Engineering\",\"logo_url\":\"https:\\/\\/klnce.edu\\/images\\/Common_wrapper4.gif\",\"primary\":\"1E3A8A\",\"secondary\":\"0F172A\",\"accent\":\"D97706\"},\"speaker_notes\":true}', '2026-08-26 08:21:15', '2026-08-26 08:21:15'),
